def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda x: sum(row.count(x) for row in grid))
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg:
                continue
            for dr, dc in ((1, 1), (1, -1)):
                rr, cc = r + dr, c + dc
                if 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == color:
                    for sign in (-1, 1):
                        y, x = r, c
                        while 0 <= y < h and 0 <= x < w and grid[y][x] in (bg, color):
                            if grid[y][x] == bg:
                                out[y][x] = color
                            y += sign * dr
                            x += sign * dc
    return out
